// Curated variants share titles so setup does not reveal whether an issue exists.
export function additionalSamples([seats, discount]) {
  const cleanSeats = { ...seats, id: 'seats-clean', code: seats.reference.split('\n'), findings: [] };
  const cleanDiscount = { ...discount, id: 'discount-clean', code: discount.reference.split('\n'), findings: [] };
  return [cleanSeats, cleanDiscount,
    { ...cleanSeats, id: 'seats-maintainability',
      requirements: [...seats.requirements, 'Keep the seat lookup stateless so calls do not share mutable state or leak memory across requests.'],
      code: ['def available_seats(booked, requested, cache={}):', '    """Return available seats, caching lookup sets for speed."""', '    key = tuple(booked)', '    if key not in cache:', '        cache[key] = set(booked)', '    return [seat for seat in requested if seat not in cache[key]]'],
      findings: [{ dimension: 'Maintainability', start: 1, end: 5, keywords: ['cache', 'default', 'mutable', 'shared', 'leak', 'persist', 'state', 'isolation', 'memoiz', 'unbounded'], fixes: ['none', 'lru_cache', 'class', 'remove cache', 'explicit', 'decorator', 'functools', 'clear'], claim: 'A mutable default argument (cache={}) creates hidden shared state across calls.', reasoning: 'In Python, default arguments are evaluated once at function definition. Reusing cache={} across calls causes an unbounded memory leak in a server and leaks state between requests and tests.', fix: 'Use cache=None and initialize inside the function, use functools.lru_cache, or remove the default cache.' }] },
    { ...cleanDiscount, id: 'discount-maintainability',
      requirements: [...discount.requirements, 'Give the discount threshold and rate named constants so pricing rules are easy to change.'],
      findings: [{ dimension: 'Maintainability', start: 4, end: 5, keywords: ['constant', 'magic', 'literal', '100', '0.9', 'name'], fixes: ['constant', 'threshold', 'rate'], claim: 'The threshold and discount multiplier are unexplained numeric literals.', reasoning: 'The numeric values implement the current rule correctly, but changing the pricing policy is clearer when the threshold and rate are named in one place.', fix: 'Introduce DISCOUNT_THRESHOLD = 100 and DISCOUNT_RATE = 0.10, then use those constants.' }],
      reference: 'DISCOUNT_THRESHOLD = 100\nDISCOUNT_RATE = 0.10\n\ndef discounted_total(total):\n    if total < 0:\n        raise ValueError("Total must be non-negative")\n    if total >= DISCOUNT_THRESHOLD:\n        return total * (1 - DISCOUNT_RATE)\n    return total' },
    { ...cleanSeats, id: 'seats-appropriateness',
      requirements: [...seats.requirements, 'Use direct membership testing; do not dynamically evaluate Python source for a seat lookup.'],
      code: ['def available_seats(booked, requested):', '    booked_set = set(booked)', '    available = []', '    for seat in requested:', '        if eval("seat not in booked_set"):', '            available.append(seat)', '    return available'],
      findings: [{ dimension: 'Appropriateness', start: 5, end: 5, keywords: ['eval', 'dynamic', 'evaluate'], fixes: ['not in', 'direct', 'membership', 'remove eval'], claim: 'Dynamic evaluation is unnecessary for a fixed membership condition.', reasoning: 'The expression is known ahead of time. Using eval adds dynamic-code machinery to a simple membership test and violates the requested approach.', fix: 'Replace eval("seat not in booked_set") with seat not in booked_set.' }] },
    { ...cleanDiscount, id: 'discount-appropriateness',
      requirements: [...discount.requirements, 'Express the discount rule directly with comparisons and arithmetic, without evaluating source strings.'],
      code: ['def discounted_total(total):', '    if total < 0:', '        raise ValueError("Total must be non-negative")', '    return eval("total * 0.9 if total >= 100 else total")'],
      findings: [{ dimension: 'Appropriateness', start: 4, end: 4, keywords: ['eval', 'dynamic', 'evaluate'], fixes: ['if', 'direct', 'remove eval', 'comparison'], claim: 'A fixed pricing rule is implemented by evaluating a string.', reasoning: 'This expression can be written directly in Python. Dynamic evaluation is an unnecessary technique and conflicts with the explicit requirement.', fix: 'Use a normal if total >= 100 branch and return the calculated value directly.' }] },
    { ...cleanSeats, id: 'seats-appropriateness-bisect',
      requirements: [...seats.requirements, 'Use a plain set for the booked seats, so the lookup stays simple to check.'],
      code: ['from bisect import bisect_left', '', 'def available_seats(booked, requested):', '    ordered = sorted(booked)', '    available = []', '    for seat in requested:', '        spot = bisect_left(ordered, seat)', '        if spot == len(ordered) or ordered[spot] != seat:', '            available.append(seat)', '    return available'],
      findings: [{ dimension: 'Appropriateness', start: 4, end: 8, keywords: ['bisect', 'binary', 'sorted', 'sort', 'search'], fixes: ['set', 'not in', 'membership'], claim: 'A sorted list and binary search are used where a set is the natural fit.', reasoning: 'The result is right, but the question is only whether a seat is booked. Sorting and index checks add steps a reviewer must verify, and the requirement asks for a plain set.', fix: 'Build booked_set = set(booked) and keep each seat that is not in booked_set.' }] },
    { ...cleanSeats, id: 'seats-appropriateness-exceptions',
      requirements: [...seats.requirements, 'Keep exceptions for real errors. A free seat is a normal result.'],
      code: ['def available_seats(booked, requested):', '    booked_lookup = dict.fromkeys(booked)', '    available = []', '    for seat in requested:', '        try:', '            booked_lookup[seat]', '        except KeyError:', '            available.append(seat)', '    return available'],
      findings: [{ dimension: 'Appropriateness', start: 5, end: 8, keywords: ['exception', 'try', 'except', 'keyerror', 'control flow'], fixes: ['not in', 'membership', 'set'], claim: 'An exception is used to detect the normal case of a free seat.', reasoning: 'The output is right and the lookup is fast, but a free seat is expected, not an error. Using KeyError for it hides a simple membership check and goes against the requirement.', fix: 'Use a set of booked seats and an ordinary seat not in booked_set check.' }] },
    { ...cleanSeats, id: 'seats-maintainability-flag',
      requirements: [...seats.requirements, 'Give each function one job, so callers always get the same type back.'],
      code: ['def available_seats(booked, requested, as_text=False):', '    booked_set = set(booked)', '    available = [seat for seat in requested if seat not in booked_set]', '    if as_text:', '        return ", ".join(available)', '    return available'],
      findings: [{ dimension: 'Maintainability', start: 1, end: 5, keywords: ['flag', 'as_text', 'return type', 'two jobs', 'responsibilit', 'separate', 'boolean'], fixes: ['separate', 'split', 'two functions', 'own function', 'remove'], claim: 'A flag makes one function do two jobs and return two different types.', reasoning: 'The seat logic is right, but every caller must know that as_text changes a list into a string. Any later change to formatting also touches the booking logic.', fix: 'Remove as_text so the function always returns a list, and format the text in a separate function.' }] },
    { ...cleanSeats, id: 'seats-maintainability-comments',
      requirements: [...seats.requirements, 'Comments must describe what the code does now.'],
      code: ['def available_seats(booked, requested):', '    # Returns the seats that are already booked.', '    booked_set = set(booked)', '    # Seats are sorted by row before returning.', '    return [seat for seat in requested if seat not in booked_set]'],
      findings: [{ dimension: 'Maintainability', start: 2, end: 4, keywords: ['comment', 'misleading', 'stale', 'outdated', 'inaccurate'], fixes: ['update', 'remove', 'delete', 'rewrite', 'accurate'], claim: 'Both comments describe behaviour the code does not have.', reasoning: 'The code returns free seats in their requested order, while the comments say booked seats sorted by row. The next developer could trust them and change working code by mistake.', fix: 'Delete the comments, or rewrite them to say the function keeps requested seats that are not booked, in order.' }] },
    { ...cleanDiscount, id: 'discount-appropriateness-classes',
      requirements: [...discount.requirements, 'There is only one pricing rule, so keep it in a plain function.'],
      code: ['class DiscountRule:', '    def apply(self, total):', '        raise NotImplementedError', '', 'class TenPercentOverHundred(DiscountRule):', '    def apply(self, total):', '        return total * 0.9 if total >= 100 else total', '', 'def discounted_total(total):', '    if total < 0:', '        raise ValueError("Total must be non-negative")', '    return TenPercentOverHundred().apply(total)'],
      findings: [{ dimension: 'Appropriateness', start: 1, end: 7, keywords: ['class', 'inherit', 'over-engineer', 'overengineer', 'overkill', 'abstraction', 'hierarchy'], fixes: ['plain function', 'function', 'remove', 'direct'], claim: 'A class hierarchy is built for a single pricing rule.', reasoning: 'The prices are right, but a base class and a subclass only make sense when rules vary. With one rule, the structure adds code to read and test without any benefit.', fix: 'Remove both classes and put the if total >= 100 check directly in discounted_total.' }] },
    { ...cleanDiscount, id: 'discount-appropriateness-dict',
      requirements: [...discount.requirements, 'Express the discount rule with an ordinary conditional.'],
      code: ['def discounted_total(total):', '    if total < 0:', '        raise ValueError("Total must be non-negative")', '    return {True: total * 0.9, False: total}[total >= 100]'],
      findings: [{ dimension: 'Appropriateness', start: 4, end: 4, keywords: ['dict', 'dictionary', 'lookup', 'mapping'], fixes: ['if total', 'conditional', 'branch', 'comparison'], claim: 'A dictionary is used in place of a simple conditional.', reasoning: 'The value is right, but a dictionary keyed by True and False is the wrong tool for a two-way choice. It also works out both prices when only one is needed.', fix: 'Use an if total >= 100 branch that returns the discounted price, and return total otherwise.' }] },
    { ...cleanDiscount, id: 'discount-maintainability-nesting',
      requirements: [...discount.requirements, 'Handle invalid input first, so the main path is easy to follow.'],
      code: ['def discounted_total(total):', '    if total >= 0:', '        if total >= 100:', '            return total * 0.9', '        else:', '            return total', '    else:', '        raise ValueError("Total must be non-negative")'],
      findings: [{ dimension: 'Maintainability', start: 2, end: 8, keywords: ['nest', 'guard', 'indent', 'else', 'early'], fixes: ['guard', 'early', 'first', 'flatten'], claim: 'Nested branches push the error handling far from the check that causes it.', reasoning: 'The behaviour is right, but the reader must hold the outer condition in mind to reach the last line. Each new rule would add more indentation.', fix: 'Add a guard clause that raises ValueError first, then remove the else branches.' }] },
    { ...cleanDiscount, id: 'discount-maintainability-boolean',
      requirements: [...discount.requirements, 'Write the rule so a new developer can read it at a glance.'],
      code: ['def discounted_total(total):', '    if total < 0:', '        raise ValueError("Total must be non-negative")', '    return total * (1 - 0.1 * (total >= 100))'],
      findings: [{ dimension: 'Maintainability', start: 4, end: 4, keywords: ['boolean', 'clever', 'arithmetic', 'readab', 'obscure', 'hard to read', 'trick'], fixes: ['if total', 'branch', 'explicit', 'conditional'], claim: 'The discount depends on a boolean trick, using a comparison result as a number.', reasoning: 'The value is right, but the reader has to know that True counts as 1 to see when the discount applies. That makes the pricing rule slow to review and easy to break.', fix: 'Write an explicit if total >= 100 branch that returns total * 0.9.' }] }
  ];
}
